<?php

use XcVm\Core\Auth\Authorization;
use XcVm\Domain\Stream\ConnectionTracker;

$xtreampiPageScripts = ['assets/xtreampi/proxies.js'];
$xtreampiCanEdit = Authorization::check('adv', 'edit_server');
$xtreampiCanConnections = Authorization::check('adv', 'live_connections');
$xtreampiProxies = array_filter($rServers ?? [], static fn(array $server): bool => (int) ($server['server_type'] ?? 0) === 1);
$xtreampiStatus = static function (array $server): array { if (empty($server['enabled'])) return ['disabled', 'Disabled']; if (!empty($server['server_online'])) return ['online', 'Online']; return match ((int) ($server['status'] ?? 0)) { 3, 5 => ['installing', 'Provisioning'], 4 => ['warning', 'Install failed'], default => ['offline', 'Offline'] }; };
?>
<section class="sc-inventory" data-sc-proxy-inventory>
    <div class="sc-page-heading"><div><p class="sc-eyebrow">Infrastructure</p><h1>Proxies</h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="servers"><i class="fe-chevron-left" aria-hidden="true"></i> Back to servers</a><a class="sc-button sc-button-primary" href="server_install?proxy"><i class="fe-plus" aria-hidden="true"></i> Install proxy</a></div></div>
    <div class="sc-toolbar"><label class="sc-search-field"><i class="fe-search" aria-hidden="true"></i><span class="sc-visually-hidden">Search proxies</span><input type="search" placeholder="Search proxy name, domain, or IP" data-sc-proxy-search></label><label class="sc-filter-field"><span>Status</span><select data-sc-proxy-status><option value="all">All statuses</option><option value="online">Online</option><option value="offline">Offline</option><option value="disabled">Disabled</option><option value="installing">Provisioning</option><option value="warning">Install failed</option></select></label></div>
    <div class="sc-inventory-grid"><?php foreach ($xtreampiProxies as $xtreampiProxy): [$xtreampiStatusKey, $xtreampiStatusLabel] = $xtreampiStatus($xtreampiProxy); $xtreampiWatchdog = json_decode((string) ($xtreampiProxy['watchdog_data'] ?? ''), true) ?: []; $xtreampiParentIds = is_array($xtreampiProxy['parent_id'] ?? null) ? $xtreampiProxy['parent_id'] : (json_decode((string) ($xtreampiProxy['parent_id'] ?? '[]'), true) ?: []); $xtreampiParents = array_values(array_filter(array_map(static fn($id) => ($rServers[(int) $id]['server_name'] ?? null), $xtreampiParentIds))); $xtreampiConnections = (int) ConnectionTracker::getLiveConnections((int) $xtreampiProxy['id'], true); $xtreampiDomain = trim(explode(',', (string) ($xtreampiProxy['domain_name'] ?? ''))[0]); $xtreampiSearch = strtolower(implode(' ', [$xtreampiProxy['server_name'] ?? '', $xtreampiProxy['server_ip'] ?? '', $xtreampiDomain])); ?><article class="sc-inventory-card" data-sc-proxy-card data-status="<?php echo $xtreampiStatusKey; ?>" data-search="<?php echo htmlspecialchars($xtreampiSearch, ENT_QUOTES, 'UTF-8'); ?>"><header class="sc-inventory-card-header"><div class="sc-server-identity"><span class="sc-status-dot is-<?php echo $xtreampiStatusKey; ?>" aria-hidden="true"></span><div><h2><?php echo htmlspecialchars((string) $xtreampiProxy['server_name'], ENT_QUOTES, 'UTF-8'); ?></h2><p>Proxy server</p></div></div><span class="sc-status-badge is-<?php echo $xtreampiStatusKey; ?>"><?php echo $xtreampiStatusLabel; ?></span></header><div class="sc-inventory-card-body"><div class="sc-server-addresses"><div><span>Public IP</span><strong><?php echo htmlspecialchars((string) ($xtreampiProxy['server_ip'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div><span>Domain</span><strong><?php echo $xtreampiDomain !== '' ? htmlspecialchars($xtreampiDomain, ENT_QUOTES, 'UTF-8') : '—'; ?></strong></div></div><div class="sc-server-kpis"><div><span>Connections</span><strong><?php echo number_format($xtreampiConnections); ?><small> / <?php echo number_format((int) ($xtreampiProxy['total_clients'] ?? 0)); ?></small></strong></div><div><span>CPU</span><strong><?php echo !empty($xtreampiProxy['server_online']) ? (int) ($xtreampiWatchdog['cpu'] ?? 0) : 0; ?>%</strong></div><div><span>RAM</span><strong><?php echo !empty($xtreampiProxy['server_online']) ? (int) ($xtreampiWatchdog['total_mem_used_percent'] ?? 0) : 0; ?>%</strong></div><div><span>Latency</span><strong><?php echo !empty($xtreampiProxy['server_online']) ? number_format((float) ($xtreampiProxy['ping'] ?? 0), 0) : '—'; ?> <small>ms</small></strong></div></div><div class="sc-server-addresses"><div><span>Coverage</span><strong><?php echo htmlspecialchars(implode(', ', $xtreampiParents) ?: 'No servers selected', ENT_QUOTES, 'UTF-8'); ?></strong></div><div><span>Capacity</span><strong><?php echo number_format((float) ($xtreampiProxy['network_guaranteed_speed'] ?? 0), 0); ?> Mbps</strong></div></div></div><footer class="sc-inventory-card-footer"><span>#<?php echo (int) $xtreampiProxy['id']; ?></span><div><?php if ($xtreampiCanConnections): ?><a href="live_connections?server=<?php echo (int) $xtreampiProxy['id']; ?>">Connections</a><?php endif; ?><a href="server_view?id=<?php echo (int) $xtreampiProxy['id']; ?>">Monitor</a><?php if ($xtreampiCanEdit): ?><a class="sc-card-primary-action" href="proxy?id=<?php echo (int) $xtreampiProxy['id']; ?>">Edit</a><?php endif; ?></div></footer></article><?php endforeach; ?></div><div class="sc-data-panel sc-proxy-empty-panel" data-sc-proxy-empty<?php echo $xtreampiProxies ? ' hidden' : ''; ?>><div class="sc-table-scroll"><table class="sc-data-table"><tbody><tr><td class="sc-table-state">No proxies have been installed yet.</td></tr></tbody></table></div></div>
</section>
